"""Collection path: CCD_EC OFF / CCD_EA ON, then four named flippers."""
import math
from labremote.runtime.workflow_result import WorkflowResult
from labremote.runtime.errors import OperationCancelled

def main(devices):
    p=devices.parameters
    delay=p.get('settle_s',1.0)
    names=dict(EC_MIRA='EC_MIRA',EA_MIRA='EA_MIRA',ec_pmt='ec_pmt',ea_pmt='ea_pmt')
    names.update(p.get('flippers',{}))
    if set(names)!={'EC_MIRA','EA_MIRA','ec_pmt','ea_pmt'} or any(not isinstance(v,str) or not v.strip() for v in names.values()) or len(set(names.values()))!=4:
        raise ValueError('Configure four distinct flipper instrument names')
    if type(delay) not in (float,int) or not math.isfinite(delay) or not 0<=delay<=60:raise ValueError('settle_s must be 0..60')
    # Resolve every device before changing any output.
    fpga=devices.fpga(p.get('fpga','fpga_local'))
    targets=[(names[k],devices.flip(names[k]),position) for k,position in [('EC_MIRA',1),('EA_MIRA',1),('ec_pmt',1),('ea_pmt',2)]]
    try:
        devices.wait(0)
        fpga.set_output('CCD_EC',False).wait()
        fpga.set_output('CCD_EA',True).wait()
        observed={}
        for name,flipper,position in targets:
            devices.wait(0);flipper.move(position).wait()
            actual=flipper.position().wait()
            if actual!=position:raise RuntimeError(f'{name}: requested position {position}, observed {actual}')
            observed[name]=actual
        devices.wait(delay)
        return WorkflowResult(reason='RE optical path configured',cleanup_status='not_required',
            value=dict(fpga_outputs={'CCD_EC':False,'CCD_EA':True},flippers=observed,settle_s=delay))
    except OperationCancelled:raise
    except Exception as exc:
        return WorkflowResult(status='failed',reason='RE setup failed: '+str(exc),continue_allowed=False,cleanup_status='unknown')

"""Remote entanglement using a frozen settings snapshot; MW source is external."""
from labremote.entanglement import config

def main(devices):
    p=devices.parameters;c=config.validate(p['settings'])
    return devices.fpga(p.get('fpga','fpga_local')).run_entanglement(
        settings=c,directory=devices.run_directory or p.get('directory')).wait()

"""SPAM detection path: CCD_EC ON / CCD_EA OFF. No flipper or MW changes."""
import math
from labremote.runtime.workflow_result import WorkflowResult
from labremote.runtime.errors import OperationCancelled

def main(devices):
    p=devices.parameters;delay=p.get('settle_s',1.0)
    if type(delay) not in (int,float) or not math.isfinite(delay) or not 0<=delay<=60:raise ValueError('settle_s must be 0..60')
    fpga=devices.fpga(p.get('fpga','fpga_local'))
    try:
        devices.wait(0)
        fpga.set_output('CCD_EA',False).wait()
        fpga.set_output('CCD_EC',True).wait()
        devices.wait(delay)
        return WorkflowResult(reason='SPAM optical path configured',cleanup_status='not_required',
            value=dict(fpga_outputs={'CCD_EC':True,'CCD_EA':False},settle_s=delay))
    except OperationCancelled:raise
    except Exception as exc:
        return WorkflowResult(status='failed',reason='SPAM setup failed: '+str(exc),continue_allowed=False,cleanup_status='unknown')

"""EA then EC SPAM; uses both chamber settings snapshots and external MW sources."""
from pathlib import Path
from labremote.characterization import pulse_experiment
from labremote.runtime.workflow_result import WorkflowResult

def main(devices):
    p=devices.parameters
    settings={ch:pulse_experiment.validate('spam',p['settings'][ch]) for ch in ('EA','EC')}
    if any(settings[ch]['chamber']!=ch for ch in settings):raise ValueError('SPAM chamber/settings mismatch')
    fpga=devices.fpga(p.get('fpga','fpga_local'));reports={};paths=[]
    for ch in ('EA','EC'):
        devices.wait(0)
        folder=str(Path(devices.run_directory)/ch) if devices.run_directory else p.get('directory')
        report=fpga.run_spam(ch,settings=settings[ch],directory=folder,frequency_hz=p.get('frequency_hz',{}).get(ch)).wait()
        reports[ch]=report
        if isinstance(report,dict) and report.get('folder'):paths.append(report['folder'])
        if not isinstance(report,dict) or report.get('status')!='completed':
            return WorkflowResult(status='cancelled' if isinstance(report,dict) and report.get('status')=='cancelled' else 'failed',
                reason=ch+' SPAM did not complete',continue_allowed=False,result_paths=paths,value=reports)
    return WorkflowResult(result_paths=paths,value=reports)
